namespace GameNight.Menus;

/// <summary>What's new in the native app, newest first (shown from the home screen).</summary>
public static class PatchNotes
{
    public static readonly (string v, string note)[] All =
    {
        ("0.61", "No crowd noise behind the menus any more: the home screen and every other menu are quiet apart from their own button sounds. The crowd comes in when a real match starts."),
        ("0.60", "The club crest on the home page no longer has the sweeping reflection across it."),
        ("0.59", "Pack openings are centred: each card arrives and flips in the middle of the screen, then slides over so the card and its details sit centred together, on any phone width."),
        ("0.58", "New app icon: a pixel football under the floodlights, as a proper Android adaptive icon (and a themed one). New loading screen: the floodlights clunk on, the ball drops onto the centre spot and bounces to rest, and GAMENIGHT slams in over a scoreboard loading bar."),
        ("0.57", "Cleaner through balls: the stick now picks the team-mate making the run, not just where he stands; long through balls are struck firm instead of dying in front of defenders; and a ball aimed past a nearby defender is zipped past him."),
        ("0.56", "Without PRESS your defender now chases and presses exactly as with it, flat out included, just getting going 10% slower. PRESS still adds the tackle. Running hard costs stamina either way."),
        ("0.55", "Red cards: a second yellow sends the player off, and a wild late slide from behind can be a straight red. He walks off over the touchline and his side plays on a man short. Keepers are never sent off."),
        ("0.54", "Gameplay fixes: a late penalty is always taken before the whistle; keepers may catch headers and deflections off their own defenders; your keeper can't carry the ball out of his box and plays it after six seconds; strikers leave keepers with the ball alone; no tackling dead balls."),
        ("0.53", "New cards in the FUT style: a shaped card per tier, rating and position over flag and club crest, a name plate and six stats, with bronze lines, silver streaks, gold lattice, neon Legends and rayed Icons. New Ultimate pack and five special packs: Strikeforce, Iron Wall, Safe Hands, One Nation and Signature."),
        ("0.52", "Stadium builder: SURPRISE ME stays on screen when you tap to hide the menus, so you can keep rolling new stadiums with the view clear."),
        ("0.51", "Every stand set now has a finished outside: a base storey in its own material with a band in your club colour, lit gates with canopies, and its own ramp drums, steel stairs or stair towers. Glass facades glow evenly at night instead of looking patchy."),
        ("0.50", "Playstyle icons: each of the 20 playstyles has its own little picture (a shield for Tank, a bolt for Rapid, an eye for Maestro, a cat for Cat...) in its badge on the card, on your squad's pitch and in the squad list."),
        ("0.49", "Mystery walkouts: after the clues your new star walks out of the players' tunnel through the smoke as a silhouette, then the lights slam on and there he is in his kit, celebrating as his name lands. No more goal roar when packs reveal."),
        ("0.48", "Goalkeepers rebuilt: the ball sits in their gloves, caught where it meets them and gathered in. They step across for what they can reach and dive only for what they can't, rush one-on-ones, come for crosses, then roll, throw or punt it out."),
        ("0.47", "A gift: every club gets 1,000,000 coins, once. Open the store and go wild."),
        ("0.46", "The stadium plays only your crowd recordings now: no more synthesised drums, claps, applause, whistlers, boos, PA chimes, rain or thunder. The recorded crowd still rises with the danger, surges at the goal line and roars for goals; ball, whistle and net sounds stay."),
        ("0.45", "New home screen: your club hangs as a banner in its colours, tonight's match is a ticket split between both clubs, everything else in a dock of tiles. The club studio gets a tab rail, a lit showroom stage, colour wells, shirt previews for every design and a SURPRISE ME for kits."),
        ("0.44", "SURPRISE ME in the stadium builder now builds stadiums that look designed: both ends and the corners mirror each other, one stand set or two, in one colour or two (often your club's)."),
        ("0.43", "LEAGUES, rebuilt: a new button opens a pixel relief map of Europe with 17 leagues. Pick your home country and start in its local league; league titles are trophies that unlock the regional associations, then the premiers, then the star-filled Golden League. Bigger leagues pay more."),
        ("0.42", "Goal explosions: when you score, the net goes up Rocket League style. Pick yours from ten in the club studio's new GOAL tab, with a live preview: Supernova, Fireworks, Thunderstrike, Volcano, Black Hole, Frostbite, Party Cannon, Arcade, Phoenix or Meteor. Replays show it again."),
        ("0.41", "The crowd is your real recordings again, as in the browser game: a seamless, ever-shifting stadium bed that rises with the danger and surges near the goal line, the full goal roar held through the celebration, penalties at full cry, with drums, claps and whistles on top."),
        ("0.40", "Choose what surrounds your stadium in the builder: the seaside city, Downtown among the towers, an Old Town of red roofs by a river with a castle, the Docklands with cranes and terraces, Countryside fields and farms, or an Alpine valley with a lake and snowy peaks."),
        ("0.39", "Playstyles: cards rated 85 or more may carry up to three of 20 special styles (Tank, Rapid, Maestro, Poacher, Cat and more). Each lifts a group of stats for real in matches, shows as a badge on the card, in the player sheet and in the pack walkout."),
        ("0.38", "A real build-up before kick-off: the teams wait in the tunnel and walk out into a roar, the camera tracking beside the captains; the announcer reads both line-ups name by name, cheered and whistled; then everyone jogs to their marks as the camera rises straight into play."),
        ("0.37", "Teams play like teams: pass and move one-twos, full-backs overlapping while the winger cuts in, strikers coming short as a partner spins in behind, fast counters, first-time lay-offs, pressing traps, the back line squeezing up, and sides chasing or seeing out games late."),
        ("0.36", "Five new stand sets in the builder: Membrane (white fabric peaks on masts), Brutalist (raw concrete and raking frames), Barrio (three steep tiers stacked high), Timber (arched wooden roof grown green) and Lumen (a cushioned skin that glows in your colour at night)."),
        ("0.35", "Slide tackles win the ball far more often: the slide now aims where the ball will be when your boot gets there (near balls straight away, far ones further ahead), both legs sweep it, and a ball run into the slider's body is stopped too."),
        ("0.34", "Stronger automatic defending: your player closes the carrier down and races loose balls flat out by himself. The stick now only nudges his run, unless you point it back against it. Running hard costs stamina, button or not. PRESS still adds the tackle."),
        ("0.33", "Your stadium now stands at the edge of a city by the sea: a plaza, boulevards, car parks and a fan zone, modern blocks and parks, a palm promenade, beach, lighthouse and boats, green hills inland, and the big city's skyline across the bay, lit up at night."),
        ("0.32", "A new crowd, built from scratch: thousands of voices that talk, buzz, roar and sing, rising as your team closes in and sinking when it fizzles. Songs swell out of the ends in time and fade back, with oohs, groans, eruptions, applause, whistles, laughter and the PA."),
        ("0.31", "In the stadium builder, tap the stadium itself to hide the menus and see it alone, centred; tap again to bring them back. Dragging, sliding and pinching still work while they are hidden."),
        ("0.30", "Smooth motion in the menus: cards rising in the pack opening, the pack dropping and bobbing, walkout slams, the summary deal, pop-ups and toasts now glide at full frame rate instead of moving in steps."),
        ("0.29", "Pitch invaders: every game minute there is a tiny chance a fan jumps the boards. Play stops, the camera follows him, the stewards in high-vis give chase while the crowd laughs and cheers, and once they walk him off the referee drops the ball. Hold FOUL to call one."),
        ("0.28", "LEAGUE mode: draw a 16-club league of made-up rivals (crests, kits, squads), play your 30 matchdays home and away, watch scores come in from around the grounds with the table moving live, read the paper every morning, chase the golden boot, prize money and the trophy."),
        ("0.27", "Your giant tifo now drops in your own stadium too: build the main stand from Arena, The Wall or Orbital and it unrolls from the roof at the walk-out and kick-off, sized to the stand. The builder marks the sets that carry it."),
        ("0.26", "Pressing is automatic now: without touching anything your player closes the carrier down and gets tight goal-side, squeezing him. Holding PRESS adds the sprint and the last step, a foot in to take the ball."),
        ("0.25", "Paint your stadium: in the builder each stand set has 16 colours (its own, your club's, and 14 more) for its main colour, saved with your plan. Drag the stadium to turn round it and tilt; two fingers slide across it and pinch to zoom."),
        ("0.24", "The crowd sounds real: the ends sing their songs in voice, the capo calls and the end answers, groans, applause for saves, whistles at time-wasting, the PA calls your scorer and the end roars his name back. Each ground sounds its own; the end nearest the camera is loudest."),
        ("0.23", "One PRESS / SPRINT button: in defence hold it to close the carrier down tight and poke the ball away. Without it your player shadows him goal-side and meets loose balls himself; pointing the stick away takes over. Through balls go where you aim, the hold sets how far ahead."),
        ("0.22", "Five more stadium sets in the builder: Harbour (containers and cranes), Pagoda (temple roofs and lanterns), Deco (1930s cream and gold with a clock tower), Crater (a volcano bowl with lava seams) and Orbital (the biggest, under a floating halo). Mix them with the first five."),
        ("0.21", "FPS LIMIT in the pause menu: pick 60, 90 or 120 frames a second. A lower limit keeps the phone cooler and the battery fuller; it is remembered between matches."),
        ("0.20", "Back to 120 fps: the 0.17 frame pacing change held the game at 60 to 70 fps even though the phone had plenty of headroom. Android frame pacing is now off, so every frame is shown as soon as it is ready at the screen's full rate."),
        ("0.19", "Lighter players: each figure uses fewer facets (the same look at pixel size), and the referee's team no longer draws 19 invisible bodies, cutting most of the triangles the players and their shadows cost."),
        ("0.18", "The FOUL button is back beside pause, like the browser game: tap it for a free kick to you where the ball is."),
        ("0.17", "Smoother 120 fps: frame pacing now always holds the full refresh rate with one more frame queued, so a small hiccup no longer drops a whole frame. The HUD and controls compile during the walk-out, not at kick-off. Truer performance reports."),
        ("0.16", "Build your own stadium: tap STADIUM on the home screen and pick a stand for each side, end and corner from five sets (Arena, Terrace, Curva, The Wall, Citadel). Any mix joins up, the stadium builds behind you as you pick, and Your stadium is a ground to play at."),
        ("0.15", "With FPS DETAIL on, the pause menu has SAVE PERFORMANCE REPORT: a small text file in Downloads (and copied, ready to paste) with your phone, settings, every spike and its cause, and the last ten minutes of frame timings."),
        ("0.14", "FPS DETAIL now catches spikes: a live frame-time graph, and for each hitch what caused it (a garbage collection, a shader compiling, the GPU, a part of the game, or Android itself), how many ms it cost and what was happening in the match."),
        ("0.13", "Pick the weather in the pause menu (MATCH: EVENING, SUNNY DAY or RAINY NIGHT); it switches at once and is remembered. In the rain the pitch soaks dark with standing water that catches the floodlights, the rain hisses, and thunder rolls after each flash."),
        ("0.12", "See where the phone's power goes: tap FPS COUNTER in the pause menu twice for DETAIL. It shows the frame time, GPU against CPU, the engine's step, draw calls, and a ranked bar for each part of the game."),
        ("0.11", "Sound no longer stays off after you leave a match from the pause menu. The goal nets have smaller holes, in a softer grey, and still show from the match camera."),
        ("0.10", "The goal nets now look like real nets in a match: a diamond mesh of cord you can see from the normal camera, not a faint haze, still bulging and rippling when the ball hits them."),
        ("0.9", "Shot aim fixed from wide: the stick now picks the post it points at as seen from the ball, so cutting in from the wing you can go near post by pointing at it. Stick idle always means far post."),
        ("0.8", "Each download now carries its version in the file name (GameNight-0.8.x.apk) and still installs as an update over the one you have."),
        ("0.7", "The buttons change with the moment, like the browser game: gold celebration moves after you score (the one you pick lights up), Whip, Short, Float on your corners, Drive, Short, Float on goal kicks, and Dive in goal at training."),
        ("0.6", "A referee and two linesmen run the match: the ref points for fouls and free kicks, the linesmen flag offsides and throw-ins. Real goals with round posts and a cord net that bulges and ripples when the ball hits it. The pitch lines no longer flicker."),
        ("0.5", "Far more crest options: 19 shapes, 24 fields, patterns, 32 emblems, new borders, low-band and monogram lettering, a pixel face. Surprise me now picks matching colours too."),
        ("0.4", "Opening packs is a show now: a lit vault, the pack cracking and tearing open, cards charging up and flipping with foil shine, a lights-out walkout for Legendary and Icon cards, and reveal-all dealing the rest out. The store glows too."),
        ("0.3", "Make the club yours: a crest maker (shapes, fields, emblems, lettering, stars), your own pictures for the tifos, the stand banner's words and colour, and your manager's look and temper. The crest now shows on the home screen, the shirt and the results."),
        ("0.2", "The menus come home: launch splash, home screen, your club, squad and line-ups, the store with pack openings, training drills and full-time results. Your club is saved on the phone."),
        ("0.1", "First native build: the real match engine on its own thread at 120 Hz, an evening pitch, the PWA's camera and controls."),
    };
}
